INSERT INTO feature VALUES('derive-over-codes','metaprograms','Derivations over levitated codes',NULL,'partial','notable',NULL,'A definition written `Eq.generic(T)` reads the data declaration `T`''s levitated code — its constructor table, each constructor''s product spine, a `var` as the recursion and each leaf at the type it names — and derives closed core the checker judges as written and the kernel replays, so the derivation is never trusted. A code with a parameter and a `rec` pair read as two codes of one sort are refused (#2345); the derivation is not yet a gandr function over a code value (#2343).','surface-lowering core-term','corpus/model/metaprograms/derive-eq-over-codes.gandr corpus/pathological/metaprograms/derive-eq-over-codes.gandr','corpus/ledger/features/derive-over-codes.gandr','#2345 #2343');
